"use strict";exports.id=603,exports.ids=[603],exports.modules={3603:a=>{a.exports=JSON.parse('{"meta":{"title":"Cocoso — Topluluk İşbirliği Yazılımı","description":"Topluluklar, kooperatifler ve gruplardan oluşan federasyonlar i\xe7in a\xe7ık kaynaklı yazılım — takvim, kaynaklar, etkinlikler, gruplar, esnek sayfalar ve daha fazlası, her zaman kendi koşullarınızla."},"brand":{"title":"COCOSO","slogan":"Topluluk İşbirliği Yazılımı"},"nav":{"home":"Ana Sayfa","features":"\xd6zellikler","examples":"\xd6rnekler","contact":"İletişim","sourceCode":"Kaynak kodu","getStarted":"\xd6zellikleri Keşfet","demo":"Canlı Demo","language":"Dil"},"home":{"leadTitle":"\xd6zerk, Federe Topluluklar i\xe7in Yazılım","lead":["Cocoso, \xf6zerk topluluklar i\xe7in a\xe7ık kaynaklı bir yazılımdır: herkese a\xe7ık bir web sitesi ve bir intranet, tek bir yerde. Kendi işlerini kendi koşullarıyla y\xfcr\xfctmek isteyen kooperatifler, eko k\xf6yler, sanat\xe7ı girişimleri, festivaller ve gr\xe4srot toplulukları i\xe7in tasarlandı.","Tek giriş. Bir\xe7ok topluluk. Verileriniz, her zaman sizin."],"leadTags":["\xc7evrimi\xe7i Platformlar","Kooperatifler","Kar Amacı G\xfctmeyen Kuruluşlar","Festivaller","Konferanslar","Bağımsız Sanat İnisiyatifleri","Eko K\xf6yler","Topluluklar","Kamp Siteleri"],"tripleTitle":"Bir Web Sitesinden \xc7ok Daha Fazlası","tripleTags":["Herkese A\xe7ık Web Sitesi","Topluluk Ağı","Verimlilik Aracı"],"triple":["Cocoso herkese a\xe7ık bir web sitesidir; b\xf6ylece d\xfcnya kim olduğunuzu, ne yaptığınızı ve yaklaşan etkinliklerinizi g\xf6rebilir — ayrı bir siteye gerek kalmaz.","Aynı zamanda \xf6zel bir topluluk ağıdır: \xfcyeler etkinlikleri takip edebilir, g\xfcncellemeleri paylaşabilir ve birbirleriyle bağlantıda kalabilir — reklam, algoritma veya takip olmadan. S\xf6m\xfcr\xfcs\xfc \xe7ıkarılmış bir sosyal medya.","Ve bir topluluğu y\xf6netmenin pratik tarafı i\xe7in ger\xe7ek bir verimlilik aracıdır: ortak bir takvim, kaynak rezervasyonları, katılım onayları ve herkesi aynı sayfada tutan y\xf6netim ara\xe7ları."],"federationTitle":"Federasyon","federationTags":["\xc7ok Toplumlu Ağ","Portal","Ortak Keşif","Varsayılan Olarak \xd6zerk"],"federation":["Cocoso tek bir gruba \xf6zg\xfc değildir. Tek bir kurulum, her biri kendi alan adına, kendi g\xf6r\xfcn\xfcm\xfcne, kendi \xfcyelerine sahip bağımsız toplulukların oluşturduğu koca bir federasyona ev sahipliği yapabilir — hepsi aynı zamanda daha geniş bir ağın par\xe7ası olarak keşfedilebilir kalır.","Bir federasyon, topluluklardan birini Portal olarak belirleyebilir: ziyaret\xe7ilerin her \xfcye topluluğa g\xf6z atabildiği, etkinlikleri t\xfcm ağ genelinde filtreleyebildiği ve yolunu bulabildiği ortak bir giriş kapısı. Herkes bağımsızlığını korur; ağ da b\xfct\xfcnl\xfcğ\xfcn\xfc korur.","Bir\xe7ok \xf6zerk gruptan oluşan bir hareket i\xe7in doğal bir uyum sağlar — yerel \xf6z y\xf6netimden vazge\xe7meden bir arada durmak isteyen bir eko k\xf6y, kooperatif veya gr\xe4srot inisiyatifi ağı gibi."],"accountsTitle":"Tek Giriş, Bir\xe7ok Topluluk","accountsTags":["Genel Hesaplar","Topluluğa \xd6zel Roller","Taşınabilir Kimlik","Doğrulanmış \xdcyelik"],"accounts":["Her kişinin, toplulukları nerede olursa olsun, tek bir Cocoso hesabı vardır. Burada bir kooperatife, orada bir festivale, başka bir yerde bir eko k\xf6ye katılın — kimliğiniz sizinle birlikte gelir, rol\xfcn\xfcz ve g\xf6r\xfcn\xfcrl\xfcğ\xfcn\xfcz ise her yerde ayrı ayrı belirlenir.","Y\xf6neticiler, \xfcyeleri topluluk topluluk doğrular; etkinlik yayınlama, bir grup y\xfcr\xfctme veya kaynakları yerel olarak y\xf6netme hakkını verirler — başka bir topluluğun ayarlarına veya \xfcyelerine hi\xe7 dokunmadan."],"dataTitle":"Verileriniz Size Ait","dataTags":["Takip Yok","\xdc\xe7\xfcnc\xfc Taraf Yok","Veri Egemenliği","Tasarımdan Gelen Gizlilik"],"data":["Cocoso\'da kullanıcıları g\xf6zetlemek veya verilerini takip etmek i\xe7in hi\xe7bir ara\xe7 yoktur. Hi\xe7bir bilgi \xfc\xe7\xfcnc\xfc taraf bir hizmetle veya reklamverenle paylaşılmaz — veri, onu yaratan topluluğa aittir, nokta.","Her \xfcye kendi bilgisinin ne kadarını paylaşacağına karar verir, her topluluk da etkinliklerinin ne kadarının daha geniş federasyona a\xe7ılacağına karar verir. Projelerinizi ve verilerinizi kendi koşullarınızla y\xfcr\xfct\xfcrs\xfcn\xfcz."],"openSourceTitle":"A\xe7ık Kaynak","openSourceTags":["Kendi Sunucunuzda Barındırılabilir","Topluluk Odaklı","Şeffaf","\xd6zg\xfcr Yazılım"],"openSource":["Cocoso, a\xe7ık\xe7a geliştirilen \xf6zg\xfcr, a\xe7ık kaynaklı bir yazılımdır — her satırını okuyabilir, kendi sunucunuzda \xe7alıştırabilir veya se\xe7tiğiniz bir barındırma sağlayıcısına g\xfcvenebilirsiniz. Ne bir bağımlılık ne de bir kara kutu vardır.","En eski g\xfcnlerinden beri ger\xe7ek ihtiya\xe7larını projeye geri besleyen topluluklar tarafından şekillendirilir: sanat\xe7ılar, kooperatifler, alternatif para birimi projeleri ve birlikte-yaratıcı mekanlar."],"ctaTitle":"Cocoso\'nun Yapabileceği Her Şeyi G\xf6r\xfcn","ctaBody":"Takvimden y\xf6netim paneline kadar her \xf6zellik bir webmaster değil, bir topluluk tarafından kolayca kullanılabilecek şekilde tasarlandı. İ\xe7inde neler olduğunu keşfedin.","ctaButton":"\xd6zellikleri Keşfet","ctaSecondary":"Ya da sadece merhaba deyin"},"features":{"pageTitle":"\xd6zellikler","pageLead":"Cocoso\'nun ayrıntıları — topluluğunuzun kullanabileceği her ara\xe7 ve nasıl \xe7alıştığı.","groupCommunityTitle":"Topluluğunuz İ\xe7in","groupAdminTitle":"Y\xf6neticiler İ\xe7in","activityTitle":"Aktiviteler","activityTags":["Halka A\xe7ık Etkinlikler","Rezervasyonlar","Devam Eden \xc7alışmalar","Performanslar","Sergiler","Konserler","Konferanslar","İ\xe7 Etkinlikler","Kaynak Ayırtma"],"activities":["Cocoso\'nun en eski versiyonu, \xf6nceden kayıtlı izleyiciler i\xe7in halka a\xe7ık sahne performanslarına ev sahipliği yapan, sanat\xe7ılar tarafından işletilen bir dans tiyatrosu ve ortak \xf6ğrenme alanı i\xe7in inşa edilmişti. \xd6zelleştirilebilir ve tekrarlanan etkinliklerin y\xf6netimi ve yayınlanması, rezervasyon dahil bir\xe7ok farklı \xf6zellik gerektirir. Kayıtlar e-posta yoluyla misafirlere iletilir ve etkinlik y\xf6neticileri kapıda gelişleri doğrulayabilir.","Bir resim, başlık, a\xe7ıklama ve daha fazla bilgiyle i\xe7erik oluşturulabilir, d\xfczenlenebilir veya silinebilir; ayrıca isteğe bağlı olarak birden fazla tarih ve saat i\xe7eren bir dizi tekrar da eklenebilir — b\xf6ylece y\xf6neticilerin her tekrar i\xe7in yeni bir giriş oluşturmasına gerek kalmaz."],"resourceTitle":"Kaynaklar","resourceTags":["Kaynak Paylaşımı","Ortak Kaynakların Y\xf6netimi"],"resources":["Cocoso, kaynak paylaşım s\xfcre\xe7lerinin zamanında planlanmasını ve g\xf6zden ge\xe7irilmesini sağlar. Doğrulanmış bir kullanıcı fiziksel bir kaynağı ayırttığında veya bir alan rezerve ettiğinde, bu bilgi takvim aracılığıyla kolektifin \xfcyeleriyle paylaşılır.","Takvim davetleri yoktur. Makinelerin yalnızca kendi iletişimimizi ve paylaşımımızı kolaylaştırmasına yardımcı olması gerektiğine — bizim yerimize hareket etmemesi gerektiğine inanıyoruz. Cocoso\'nun takvimi, topluluk etkinliklerinin ve kaynak paylaşımının ana y\xfcz\xfcd\xfcr; b\xf6ylece e-postalarımızı veri karmaşasından kurtardığımız gibi birbirimizle konuşmaya devam ederiz."],"calendarTitle":"Takvim","calendarTags":["Zamanlama","G\xfcndem","Ortak Kaynakların Paylaşımı","Etkinlik Programlama","Kaynak Rezervasyonları"],"calendar":["Cocoso\'nun web takvimi Aylık, Haftalık veya G\xfcnl\xfck etkinlikleri ve kaynak g\xfcncellemelerini g\xf6r\xfcnt\xfcleyebilir; kullanıcılar bu zaman dilimleri arasında tek dokunuşla gezinebilir. Her giriş bir kaynak kullanım etkinliğine veya bir topluluk etkinliğine karşılık gelebilir.","Her girişe bir kategori atanabilir — rezerve edilmiş bir kaynak veya yoga gibi bir etkinlik t\xfcr\xfc — hem halka a\xe7ık etkinlik listeleri hem de i\xe7 veya \xf6zel rezervasyonlar i\xe7in kullanışlıdır. Cocoso\'daki her \xf6zellik gibi, \xe7ok farklı kullanım durumlarına uyacak kadar kasıtlı olarak soyuttur."],"groupTitle":"Gruplar","groupTags":["\xc7alışma Grupları","Okullar","Birlikte Yaratma","Yinelenen Etkinlikler","Paylaşılan Dok\xfcmanlar","\xdcye Etkinlikleri"],"groups":["Bir Grup, bir kavramı ve bir grup insan tarafından —sanal ya da y\xfcz y\xfcze— s\xfcrd\xfcr\xfclen, bu kavrama dayalı bir dizi etkinliği temsil eder. Bir grup altında, \xfcyeler t\xfcm pratik ayrıntıları, temel bilgileri ve tarihleri tek bir sayfada belgelenmiş halde ortak etkinlikler y\xfcr\xfctebilir.","Gruplar; eğitim, sosyal veya \xf6ğrenme etkinliklerinin — tekrarlayan yoga seansları, okul d\xf6nemleri veya her t\xfcrl\xfc birlikte yaratma ve s\xfcrekli gelişen s\xfcrecin — y\xf6netilmesini sağlar. Y\xf6neticiler bir resim ve biraz metinle başlatır; basit bir forum, d\xf6k\xfcman listesi, \xfcye listesi ve tarihler tek sayfada hazır olur.","Temelde bir okulu, tekrarlayan bir dersi veya her t\xfcrden bir işbirliği etkinliğini y\xfcr\xfctmek i\xe7in gereken ara\xe7 setidir."],"workTitle":"İşler","workTags":["Portf\xf6y","Pazar Yeri","Dok\xfcmantasyon","Sunum"],"works":["Bir İş, topluluğa sergilenmek \xfczere bir sanat\xe7ı, araştırmacı, tasarımcı, zanaatkar veya satıcının g\xf6rsel ya da g\xf6rsel-işitsel bir yaratımıdır. Ayrıntılar, g\xf6rseller, ses dosyaları ve videolar, yaratıcının se\xe7tiği bir kategori i\xe7inde paylaşılabilir — hem portf\xf6yler hem de pazar yerleri i\xe7in tasarlanmış bir ara\xe7.","Bir iş, i\xe7 kullanım ve belgeleme amacıyla \xf6zel olarak da kaydedilebilir. Sanat\xe7ıların ve zanaatkarların yaptıklarını d\xfcnyayla paylaşmasını ve iletişim kurmasını, aynı zamanda kendi referansları i\xe7in bir kayıt tutmasını sağlamak \xfczere tasarlandı."],"memberTitle":"\xdcyeler","memberTags":["\xdcye Y\xf6netimi","Topluluk","\xdcyelikler","Doğrulama","Roller ve Yetkiler","Takip\xe7iler"],"members":["Y\xf6neticiler, organizasyonun her \xfcyesini tek bir yerden bulabilir, filtreleyebilir ve y\xf6netebilir: takvimde etkinlik yayınlamak veya bir grup başlatmak gibi belirli yetenekler i\xe7in kişileri doğrulayabilir veya doğrulamayı kaldırabilir.","\xd6rneğin bir yoga st\xfcdyosu işletiyorsanız, aynı platformda hem \xf6ğretmenleriniz hem de \xf6ğrencileriniz olur — \xf6ğretmenlerinizi kendi etkinliklerini oluşturabilmeleri i\xe7in doğrularsınız, \xf6ğrenciler ise sadece katılıp kaydolabilir.","Yetkiler topluluk genelinde anlamlı bir şekilde dağıtılır ve her kullanıcı kendi hesabını oluşturup oradan y\xf6netir. Parolalar otomatik olarak şifrelenir, b\xf6ylece sistem y\xf6neticileri bunları okuyamaz veya takip edemez."],"pagesTitle":"Esnek Sayfalar","pagesTags":["S\xfcr\xfckle & Bırak","A\xe7ılış Sayfaları","Kampanyalar","Statik Sayfalar","Kodsuz"],"pages":["Topluluğunuzun ihtiya\xe7 duyduğu bir a\xe7ılış sayfasını, kampanya sayfasını veya herhangi bir statik sayfayı \xf6zg\xfcrce oluşturun — metin, g\xf6rsel ve d\xfczen i\xe7in s\xfcr\xfckle-bırak bloklarla, hi\xe7 kod yazmadan. Bir zamanlar Cocoso\'nun en basit CMS\'i olan şey, artık ger\xe7ek bir sayfa oluşturucudur.","Her sayfa otomatik olarak navigasyonunuzun bir par\xe7ası olur. Bir Hakkımızda sayfası, bir şartlar seti, tek seferlik bir kampanya veya web sitenizin tamamen yeni bir b\xf6l\xfcm\xfc i\xe7in kullanın — \xf6zg\xfcrce oluşturulur, anında yayınlanır."],"adminTitle":"Y\xf6netim Paneli","adminTags":["Organizasyon Kurulumu","Marka Kimliği","Men\xfc ve Navigasyon","\xdcstbilgi ve Altbilgi","Ayarlar"],"admin":["Organizasyonunuzu sıfırdan kurmak i\xe7in \xf6zel bir y\xf6netim paneli: isim, logo, iletişim bilgileri ve topluluğunuzun kendini nasıl sunduğunu şekillendiren her ayar — hi\xe7 kod yazmadan.","Men\xfcn\xfcz\xfc, \xfcstbilginizi ve altbilginizi \xf6zelleştirin ve ziyaret\xe7ilerin ilk ne g\xf6receğine tam olarak siz karar verin. Her Cocoso topluluğunun arkasındaki kontrol odası; geliştiriciler i\xe7in değil, y\xf6neticiler i\xe7in tasarlandı."],"designTitle":"Tasarım Tercihleri","designTags":["Renkler","K\xf6şe Yuvarlaklığı","Arka Planlar","G\xf6r\xfcn\xfcm ve His"],"design":["Topluluğunuzun web sitesine kendi g\xf6rsel kimliğini verin: renklerinizi se\xe7in, k\xf6şe yuvarlaklığını ayarlayın, bir arka plan belirleyin — tek bir satır CSS\'e dokunmadan sitenizi belirgin şekilde kendinize \xf6zg\xfc hale getirin.","Tasarım tercihleri t\xfcm siteniz genelinde aynı anda uygulanır; b\xf6ylece topluluğunuzun varlığı b\xfcy\xfcrken bile ana sayfadan takvime, her esnek sayfaya kadar tutarlı kalır."],"newsletterTitle":"B\xfclten ve E-postalar","newsletterTags":["E-posta B\xfclteni","Otomatik E-postalar","\xdcye İletişimi"],"newsletter":["Ayrı bir e-posta listesi aracına gerek kalmadan bir e-posta b\xfclteniyle her \xfcyeye doğrudan ulaşın. Bir kere yazın, t\xfcm topluluğunuza g\xf6nderin ve insanları bir sosyal medya akışına g\xfcvenmeden haberdar edin.","Otomatik e-postalar rutin anları sizin i\xe7in halleder: kayıt onayları, katılım doğrulamaları ve diğer \xfcye bildirimleri kendi kendine g\xf6nderilir; b\xf6ylece y\xf6neticiler gelen kutusu yerine topluluğa odaklanabilir."]},"clients":{"pageTitle":"Kullanım \xd6rnekleri","pageLead":"Cocoso\'yu zaten kullanan ger\xe7ek topluluklar, at\xf6lyeler ve sanat\xe7ılar — federasyon ağları, paylaşılan \xe7alışma alanları, etkinlik takvimleri ve kişisel portf\xf6yler, her biri kendine g\xf6re şekillendirilmiş.","samarbetetTitle":"Samarbetet","samarbetetTags":["İsve\xe7","Federasyon","Sanat\xe7ılar ve K\xfclt\xfcr Mekanları"],"samarbetet":["Samarbetet, İsve\xe7 genelinde bağımsız toplulukların bir federasyonudur — sanat\xe7ılar, sanat mekanları, bah\xe7eler, at\xf6lyeler ve insanlar, tek bir ortak ağ altında birbirine bağlanır.","\xdcyeleri sahneleri, bah\xe7eleri, at\xf6lyeleri ve toplantı alanlarını bir araya getirir, kendi programlarını ve mağazalarını y\xfcr\xfct\xfcr, t\xfcm ekosisteme ortak bir giriş kapısından faydalanırken bağımsız kalırlar."],"samarbetetLinkLabel":"samarbetet.org\'u ziyaret edin","kkvTitle":"KKV Stockholm","kkvTags":["Kaynak Rezervasyonu","200+ Kaynak","400+ \xdcye"],"kkv":["KKV Stockholm — Konstn\xe4rernas Kollektivverkstad — profesyonel sanat\xe7ılar i\xe7in ortak bir \xe7alışma alanıdır; 400\'den fazla \xfcyeye 200\'den fazla ekipman ve at\xf6lye alanına paylaşımlı erişim sağlar.","\xdcyeler kaynakları Cocoso\'nun takvimi \xfczerinden rezerve eder, kendi portf\xf6ylerini ve herkese a\xe7ık etkinliklerini yayınlar, ortak bir \xfcye sayfasında birbirlerini bulurlar — tek bir platformda sorunsuzca y\xfcr\xfct\xfclen b\xfcy\xfck, hareketli bir at\xf6lye."],"kkvLinkLabel":"stockholm.kkv.nu\'yu ziyaret edin","hojdenTitle":"h\xf6jden","hojdenTags":["Sanat\xe7ı Girişimi Mekan","Kaynak Rezervasyonu","Portf\xf6yler"],"hojden":["h\xf6jden, Stockholm\'de sanat\xe7ılar tarafından y\xfcr\xfct\xfclen bir mekandır — 2018\'den beri Sl\xe4ktet kooperatifi tarafından kolektif olarak işletilen st\xfcdyolar, bir sahne, bir dans pisti, bir galeri ve bir mutfaktan oluşur.","KKV gibi h\xf6jden de paylaşılan alanlarının ve ekipmanlarının rezervasyonlarını, \xfcye portf\xf6ylerini ve at\xf6lye \xe7alışmaları, performanslar ve derslerden oluşan halka a\xe7ık bir programı y\xf6netmek i\xe7in Cocoso\'yu kullanır."],"hojdenLinkLabel":"hojden.house\'u ziyaret edin","gerlesborgTitle":"Gerlesborgs Kulturhus","gerlesborgTags":["K\xfclt\xfcr Merkezi","Halka A\xe7ık Etkinlikler","Takvim"],"gerlesborg":["Gerlesborgs kulturhus, İsve\xe7\'in Hamburgsund kentinde bulunan ve \xe7evresindeki topluluk i\xe7in sergiler, konserler, at\xf6lye \xe7alışmaları ve bir edebiyat festivaline ev sahipliği yapan bir k\xfclt\xfcr merkezidir.","Halka a\xe7ık programını yayınlamak i\xe7in Cocoso\'yu basit ve etkili bir şekilde kullanır — her sergi, konser ve kurs doğrudan takviminde g\xf6r\xfcn\xfcr, ayrı bir etkinlik aracına gerek kalmaz."],"gerlesborgLinkLabel":"gerlesborgskulturhus.se\'yi ziyaret edin","minaTitle":"M\xeena Kocailik","minaTags":["Portf\xf6y","Bağımsız Sanat\xe7ı"],"mina":["M\xeena Kocailik, portf\xf6y\xfcn\xfc yayınlamak i\xe7in Cocoso\'yu basit\xe7e kullanan bağımsız bir sanat\xe7ıdır: bakımı gereken hi\xe7bir ekstra olmadan, \xe7alışmalarının temiz, kendi kendine y\xf6netilen bir sergisi.","Bu, Cocoso\'nun m\xfcmk\xfcn olan en k\xfc\xe7\xfck kullanımıdır — y\xfczlerce kişiye hizmet eden federasyonlara hizmet eden aynı platformun tek bir yaratıcı uygulama i\xe7in de aynı derecede iyi \xe7alıştığının kanıtı."],"minaLinkLabel":"Portf\xf6y\xfcn\xfc ziyaret edin"},"credits":{"title":"Destekleyenler","first":"Harika bir işbirliğiyle geliştirildi:","second":"Destekleyenler"},"contact":{"title":"İletişim","heading":"Beraber \xe7alışabiliriz","body":"Cocoso\'yu kullanabileceğiniz bir projeniz var mı? Yoksa sadece merhaba demek ve arkadaş olmak mı istiyorsunuz? Bize buradan bir mesaj bırakın, size geri d\xf6nelim!","email":"E-posta adresiniz","subject":"Konu","message":"Mesaj","send":"G\xf6nder"},"footer":{"tagline":"Topluluklar, kooperatifler ve gr\xe4srot grupları federasyonları i\xe7in a\xe7ık kaynaklı yazılım — herkese a\xe7ık bir web sitesi ve \xf6zel bir intranet, her zaman kendi koşullarınızla.","exploreTitle":"Keşfet","projectTitle":"Proje","license":"\xd6zg\xfcr ve a\xe7ık kaynaklıdır, GNU GPLv3 lisansı altındadır.","bottom":"\xa9 {{year}} Cocoso. Her yerdeki \xf6zerk topluluklar i\xe7in \xfcretildi."},"source":"Kaynak"}')}};